    async function editShift(id){const row=data.rows.find(r=>r.driver_id===id),saved=(data.roster?.shifts||[]).find(s=>s.driver_id===id);if(!row||busy)return;const label=await options.prompt('填寫 '+row.driver_name+' 本月份班別，例如 04-17。',saved?.shift_label||'','編輯班別');if(label===null)return;if(label.length>40){await options.alert('班別最多40字');return;}await mutate('save_driver_roster_shift',{month:state.month,driver_id:id,label,revision:saved?.revision||0});}
