    let selection=null,quickSelect=false;
    function visibleCells(){return{rows:sortedRosterRows(),dates:rosterDates(state.month,state,todayTaipei())};}
    function selectCell(cell,extend=false){const {rows,dates}=visibleCells(),point={row:rows.findIndex(r=>r.driver_id===cell.dataset.rosterDriver),col:dates.indexOf(cell.dataset.rosterDate)};if(point.row<0||point.col<0)return;if(!extend||!selection)selection={anchor:point,end:point};else selection.end=point;paintSelection();}
    function selectedEntries(){if(!selection)return[];const {rows,dates}=visibleCells(),result=[];for(let r=Math.min(selection.anchor.row,selection.end.row);r<=Math.max(selection.anchor.row,selection.end.row);r++){const line=[];for(let c=Math.min(selection.anchor.col,selection.end.col);c<=Math.max(selection.anchor.col,selection.end.col);c++){if(!rows[r]||!dates[c])return[];const row=rows[r],note=(data.roster?.notes||[]).find(n=>n.driver_id===row.driver_id&&n.work_on===dates[c]);line.push({note:note?.note||'',color:note?.color||'',leave_day:row.submission?.status!=='rejected'&&!!row.submission?.off_dates?.includes(dates[c])});}result.push(line);}return result;}
