    function confirmInEditor(dialog,message,title){return new Promise(resolve=>{const layer=document.createElement('div');layer.className='roster-inline-confirm';layer.innerHTML='<h3>'+escape(title)+'</h3><p>'+escape(message)+'</p><footer><button type="button" class="ghost-btn" data-roster-confirm="no">取消</button><button type="button" class="primary-btn" data-roster-confirm="yes">確定</button></footer>';const form=dialog.querySelector('form');form.inert=true;dialog.append(layer);let done=false;const finish=value=>{if(done)return;done=true;layer.remove();form.inert=false;dialog.removeEventListener('cancel',cancel);dialog.removeEventListener('close',close);resolve(value);};const cancel=event=>{event.preventDefault();finish(false);},close=()=>finish(false);dialog.addEventListener('cancel',cancel);dialog.addEventListener('close',close);layer.querySelector('[data-roster-confirm=no]').onclick=()=>finish(false);layer.querySelector('[data-roster-confirm=yes]').onclick=()=>finish(true);layer.querySelector('[data-roster-confirm=yes]').focus();});}
