    function pastePlan(text){if(!selection)throw Error('請先點選貼上起點');const source=rosterClipboard?.identity===options.identity&&rosterClipboard.text===text?rosterClipboard.grid:parseRosterText(text).map(line=>line.map(note=>({note,...(note==='休假'?{leave_day:true}:note==='出車'?{leave_day:false}:{})})));const {rows,dates}=visibleCells(),origin={row:Math.min(selection.anchor.row,selection.end.row),col:Math.min(selection.anchor.col,selection.end.col)},cells=[];if(source.length*source[0].length>200||source.some(line=>line.length!==source[0].length))throw Error('貼上需為規則矩形，最多200格');for(let r=0;r<source.length;r++)for(let c=0;c<source[r].length;c++){if(!rows[origin.row+r]||!dates[origin.col+c])throw Error('貼上範圍超出目前顯示的司機或日期');cells.push(cellPatch(rows[origin.row+r].driver_id,dates[origin.col+c],source[r][c]));}return cells;}
    async function openPaste(text){const dialog=document.createElement('dialog');dialog.className='dr-roster-editor';dialog.innerHTML='<form><h3>貼上班表</h3><textarea aria-label="貼上內容" rows="5"></textarea><div data-preview></div><p role="alert" data-error></p><footer><button type="button" class="ghost-btn" data-close>取消</button><button class="primary-btn" type="submit">套用</button></footer></form>';document.body.append(dialog);dialog.showModal();dialog.onclose=()=>dialog.remove();dialog.querySelector('[data-close]').onclick=()=>dialog.close();let plan=null;const input=dialog.querySelector('textarea');input.value=text;const preview=()=>{try{plan=pastePlan(input.value);dialog.querySelector('[data-preview]').textContent=plan.length+' 格 · 休假調整 '+plan.filter(c=>c.leave_day!==undefined).length+' 格';dialog.querySelector('[data-error]').textContent='';}catch(error){plan=null;dialog.querySelector('[data-error]').textContent=error.message;}};input.oninput=preview;preview();dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(!plan||dialog.dataset.saving)return;dialog.dataset.saving='1';const button=dialog.querySelector('[type=submit]');button.disabled=true;try{if(await saveCells(plan,dialog)){dialog.close();await load(false);}}catch(error){dialog.querySelector('[data-error]').textContent=error.message;}finally{delete dialog.dataset.saving;button.disabled=false;}};}
